/**
 * PROGRAM audit-side Zod schema (L2).
 *
 * Constructed from the `Program` SDK type (generated by orval). Program is not
 * polymorphic (unlike Offer), so the schema is a single strict z.object for
 * the base shape plus a catchall wrapper for tenant extensions.
 *
 * The audit pattern mirrors the METADATA pilot:
 *   programBaseSchema   — strict z.object for the typed base fields
 *   programRecordSchema — programBaseSchema.catchall(z.unknown()) for tenant
 *                         extension keys without losing strict base-field
 *                         validation. Per playbook §5.11.
 *
 * Notable PROGRAM-specific fields vs. METADATA:
 *   - partnerId (EntityId FK, optional string)
 *   - createAccountOnCustomerCreation (boolean, optional)
 *   - programAccountIdInformation (CodeGenInformation, optional object)
 *   - type (Metadata object, required on read)
 */

import { localizedString } from "@loom-loyalty/test-utils/zod";
import { describe, expect, it } from "vitest";
import { z } from "zod";

// CodeGenInformation sub-schema (mirrors SDK type; all fields optional except type).
const codeGenInformationSchema = z
  .object({
    type: z.string().min(1),
    prefix: z.string().optional(),
    suffix: z.string().optional(),
    part1Algorithm: z.string().optional(),
    part1Length: z.number().optional(),
    part2Algorithm: z.string().optional(),
    part2Length: z.number().optional(),
    checkDigitAlgorithm: z.string().optional(),
  })
  .optional();

// Minimal Metadata sub-schema (the `type` field on Program).
const metadataRefSchema = z.object({
  code: z.string().min(1),
  name: z.string().min(1),
  typeCode: z.string().min(1),
  dataTypeId: z.string().min(1),
  metadataId: z.string().optional(),
});

const programBaseSchema = z.object({
  programId: z.string().min(1),
  code: z.string().min(1),
  name: z.string().min(1),
  type: metadataRefSchema,
  description: localizedString.optional(),
  partnerId: z.string().optional(),
  createAccountOnCustomerCreation: z.boolean().optional(),
  programAccountIdInformation: codeGenInformationSchema,
  createdDateTime: z.string().optional(),
  modifiedDateTime: z.string().optional(),
});

// Zod 4 prefers .catchall(unknown) over the deprecated .passthrough() helper.
const programRecordSchema = programBaseSchema.catchall(z.unknown());

describe("[audit] L2 — programBaseSchema (strict base shape)", () => {
  it("accepts a happy fixture with only required fields", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440000",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000001",
      },
    });
    expect(result.success).toBe(true);
  });

  it("accepts a fixture with all optional fields populated", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440001",
      code: "premium-program",
      name: "Premium Program",
      type: {
        code: "TIER",
        name: "Tier",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000002",
        metadataId: "meta_00000000000000000000000000000001",
      },
      description: { en: "Premium loyalty program", es: "Programa de lealtad premium" },
      partnerId: "part_550e8400e29b41d4a716446655440000",
      createAccountOnCustomerCreation: true,
      programAccountIdInformation: { type: "GENERATED" },
      createdDateTime: "2024-01-01T00:00:00Z",
      modifiedDateTime: "2024-01-02T00:00:00Z",
    });
    expect(result.success).toBe(true);
  });

  it("rejects a fixture missing the required `name` field", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440002",
      code: "broken-program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000003",
      },
    });
    expect(result.success).toBe(false);
    expect(result.error?.issues.some((i) => i.path[0] === "name")).toBe(true);
  });

  it("rejects an empty `code`", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440003",
      code: "",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000004",
      },
    });
    expect(result.success).toBe(false);
    expect(result.error?.issues.some((i) => i.path[0] === "code")).toBe(true);
  });

  it("rejects a description without the required `en` locale (via shared refinement)", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440004",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000005",
      },
      description: { es: "Solo español" },
    });
    expect(result.success).toBe(false);
    expect(result.error?.issues.some((i) => i.path.includes("description"))).toBe(true);
  });

  it("strips empty-string locales from description (via shared refinement)", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440005",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000006",
      },
      description: { en: "Top tier", es: "" },
    });
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.description).toEqual({ en: "Top tier" });
    }
  });

  it("strips unknown keys from base schema (no passthrough)", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440006",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000007",
      },
      tenantCustomField: "value",
      riskCategory: "LOW",
    });
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data).not.toHaveProperty("tenantCustomField");
      expect(result.data).not.toHaveProperty("riskCategory");
    }
  });

  it("accepts a valid programAccountIdInformation with type=GENERATED", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440007",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000008",
      },
      programAccountIdInformation: {
        type: "GENERATED",
        prefix: "ACC-",
        part1Algorithm: "RANDOM_ALPHANUMERIC",
        part1Length: 8,
      },
    });
    expect(result.success).toBe(true);
  });

  it("rejects programAccountIdInformation missing the required `type` field", () => {
    const result = programBaseSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440008",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000009",
      },
      programAccountIdInformation: { prefix: "ACC-" },
    });
    expect(result.success).toBe(false);
    expect(
      result.error?.issues.some(
        (i) => i.path.includes("programAccountIdInformation") && i.path.includes("type")
      )
    ).toBe(true);
  });
});

describe("[audit] L2 — programRecordSchema (catchall wrapper)", () => {
  it("preserves tenant extension keys alongside the strict base fields", () => {
    const result = programRecordSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440009",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000010",
      },
      tenantCustomField: "value",
      riskCategory: "LOW",
    });
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data).toMatchObject({
        code: "gold-program",
        tenantCustomField: "value",
        riskCategory: "LOW",
      });
    }
  });

  it("still enforces base-field validation through the catchall", () => {
    const result = programRecordSchema.safeParse({
      programId: "prog_550e8400e29b41d4a716446655440010",
      code: "broken-program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000011",
      },
      tenantCustomField: "value",
    });
    expect(result.success).toBe(false);
    expect(result.error?.issues.some((i) => i.path[0] === "name")).toBe(true);
  });

  it("survives an extension-field roundtrip end-to-end (parse → re-parse)", () => {
    const fixture = {
      programId: "prog_550e8400e29b41d4a716446655440011",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000012",
      },
      description: { en: "Top tier" },
      tenantCustomField: "value",
      riskCategory: "LOW",
      customFloat: 3.14,
      customNested: { foo: "bar" },
    };
    const first = programRecordSchema.parse(fixture);
    const second = programRecordSchema.parse(first);
    expect(second).toEqual(first);
  });

  it("still enforces strict base-field types when extension catchall is in play", () => {
    const valid = programRecordSchema.parse({
      programId: "prog_550e8400e29b41d4a716446655440012",
      code: "gold-program",
      name: "Gold Program",
      type: {
        code: "POINTS",
        name: "Points",
        typeCode: "PROGRAM_TYPE",
        dataTypeId: "dtyp_00000000000000000000000000000013",
      },
      tenantCustomField: "value",
    });
    const broken = { ...valid, code: 42 };
    const result = programRecordSchema.safeParse(broken);
    expect(result.success).toBe(false);
    expect(result.error?.issues.some((i) => i.path[0] === "code")).toBe(true);
  });
});
